<?php require __DIR__.'/includes/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$name||!$phone||strlen($pass)<8)$error='أدخل الاسم والهاتف وكلمة مرور من 8 أحرف على الأقل.';else{try{$s=db()->prepare('INSERT INTO customers(name,phone,email,password_hash) VALUES(?,?,?,?)');$s->execute([$name,$phone,$email?:null,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['customer_id']=(int)db()->lastInsertId();$_SESSION['customer_name']=$name;go('index.php');}catch(Throwable $e){$error='رقم الهاتف أو البريد مسجل مسبقاً.';}}}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إنشاء حساب</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner login"><h1>إنشاء حساب جديد</h1><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>الاسم<input name="name" required></label><label>الهاتف<input name="phone" required></label><label>البريد الإلكتروني (اختياري)<input type="email" name="email"></label><label>كلمة المرور<input type="password" name="password" minlength="8" required></label><button class="gold">إنشاء الحساب</button><p><a href="login.php">لديك حساب؟ تسجيل الدخول</a></p></form></main></body></html>